export function parseHarga(teks) {
  const m = String(teks).replace(/\./g, "").match(/\d+/);
  return m ? Number(m[0]) : 0;
}

export function parseHarga(teks) {
  if (teks === "") return 0;
  return Number(teks.replace(/\./g, "").match(/\d+/)[0]);
}

